-- Chart presets share the same database schema shape but keep preset-specific defaults.
with chart_materials(component_key, material_title, chart_kind, chart_color) as (
  values
    ('echarts-bar', '柱状图', 'bar', '#3b82f6'),
    ('echarts-line', '折线图', 'line', '#14b8a6'),
    ('echarts-area', '面积图', 'area', '#22c55e'),
    ('echarts-pie', '饼图', 'pie', '#f97316'),
    ('echarts-doughnut', '环形图', 'doughnut', '#8b5cf6'),
    ('echarts-scatter', '散点图', 'scatter', '#ec4899'),
    ('echarts-radar', '雷达图', 'radar', '#0ea5e9')
)
insert into public.lowcode_form_definitions (code, name, description, schema, enabled)
select
  'material-prop.' || component_key,
  '设计器属性 - ' || material_title,
  '数据库驱动的物料属性表单，统一使用 Tab 布局。',
  jsonb_build_object(
    'componentKey', component_key,
    'title', material_title || ' 属性',
    'fields', jsonb_build_array(
      jsonb_build_object('field', '__block._vid', 'target', 'block', 'path', '_vid', 'label', '组件 ID', 'component', 'vxe-input', 'valueKind', 'string', 'props', jsonb_build_object('disabled', true, 'clearable', false)),
      jsonb_build_object('field', 'title', 'target', 'props', 'path', 'title', 'label', '标题', 'component', 'vxe-input', 'valueKind', 'string', 'defaultValue', material_title),
      jsonb_build_object('field', 'chartType', 'target', 'props', 'path', 'chartType', 'label', '图表类型', 'component', 'lc-option-select', 'valueKind', 'raw', 'defaultValue', chart_kind, 'options', $options$[{"label":"柱状图","value":"bar","rawValue":"bar"},{"label":"折线图","value":"line","rawValue":"line"},{"label":"面积图","value":"area","rawValue":"area"},{"label":"饼图","value":"pie","rawValue":"pie"},{"label":"环形图","value":"doughnut","rawValue":"doughnut"},{"label":"散点图","value":"scatter","rawValue":"scatter"},{"label":"雷达图","value":"radar","rawValue":"radar"}]$options$::jsonb, 'props', '{}'::jsonb),
      jsonb_build_object('field', 'color', 'target', 'props', 'path', 'color', 'label', '主色', 'component', 'lc-color-picker', 'valueKind', 'string', 'defaultValue', chart_color),
      jsonb_build_object('field', 'categoriesJson', 'target', 'props', 'path', 'categoriesJson', 'label', '类目 JSON', 'component', 'lc-json-editor', 'valueKind', 'raw', 'defaultValue', '["Mon","Tue","Wed","Thu","Fri","Sat","Sun"]', 'props', jsonb_build_object('rows', 8, 'resize', 'vertical', 'jsonRootType', 'array', 'jsonValueMode', 'string')),
      jsonb_build_object('field', 'seriesDataJson', 'target', 'props', 'path', 'seriesDataJson', 'label', '数值 JSON', 'component', 'lc-json-editor', 'valueKind', 'raw', 'defaultValue', '[120,200,150,80,70,110,130]', 'props', jsonb_build_object('rows', 8, 'resize', 'vertical', 'jsonRootType', 'array', 'jsonValueMode', 'string')),
      jsonb_build_object('field', 'pieDataJson', 'target', 'props', 'path', 'pieDataJson', 'label', '饼图数据 JSON', 'component', 'lc-json-editor', 'valueKind', 'raw', 'defaultValue', '[{"name":"Direct","value":335},{"name":"Email","value":310},{"name":"Ads","value":234},{"name":"Search","value":135},{"name":"Video","value":154}]', 'props', jsonb_build_object('rows', 8, 'resize', 'vertical', 'jsonRootType', 'array', 'jsonValueMode', 'string')),
      jsonb_build_object('field', 'radarIndicatorsJson', 'target', 'props', 'path', 'radarIndicatorsJson', 'label', '雷达指标 JSON', 'component', 'lc-json-editor', 'valueKind', 'raw', 'defaultValue', '[{"name":"Sales","max":100},{"name":"Admin","max":100},{"name":"Tech","max":100},{"name":"Support","max":100},{"name":"Marketing","max":100}]', 'props', jsonb_build_object('rows', 8, 'resize', 'vertical', 'jsonRootType', 'array', 'jsonValueMode', 'string')),
      jsonb_build_object('field', 'radarDataJson', 'target', 'props', 'path', 'radarDataJson', 'label', '雷达数值 JSON', 'component', 'lc-json-editor', 'valueKind', 'raw', 'defaultValue', '[85,72,90,64,78]', 'props', jsonb_build_object('rows', 8, 'resize', 'vertical', 'jsonRootType', 'array', 'jsonValueMode', 'string')),
      jsonb_build_object('field', 'optionJson', 'target', 'props', 'path', 'optionJson', 'label', '完整 option JSON', 'component', 'lc-json-editor', 'valueKind', 'raw', 'defaultValue', '', 'help', '填写后会覆盖上方配置', 'props', jsonb_build_object('rows', 8, 'resize', 'vertical', 'jsonRootType', 'object', 'jsonValueMode', 'string')),
      jsonb_build_object('field', '__styles.justifyContent', 'target', 'styles', 'path', 'justifyContent', 'label', '组件对齐', 'component', 'lc-option-select', 'valueKind', 'raw', 'defaultValue', 'flex-start', 'options', $options$[{"label":"左对齐","value":"flex-start","rawValue":"flex-start"},{"label":"居中","value":"center","rawValue":"center"},{"label":"右对齐","value":"flex-end","rawValue":"flex-end"}]$options$::jsonb),
      jsonb_build_object('field', '__styles.tempPadding', 'target', 'styles', 'path', 'tempPadding', 'label', '统一内边距', 'component', 'vxe-input', 'valueKind', 'string', 'defaultValue', '0', 'syncTo', jsonb_build_array('paddingTop', 'paddingRight', 'paddingBottom', 'paddingLeft')),
      jsonb_build_object('field', '__styles.paddingTop', 'target', 'styles', 'path', 'paddingTop', 'label', '上内边距', 'component', 'vxe-input', 'valueKind', 'string', 'defaultValue', '0'),
      jsonb_build_object('field', '__styles.paddingRight', 'target', 'styles', 'path', 'paddingRight', 'label', '右内边距', 'component', 'vxe-input', 'valueKind', 'string', 'defaultValue', '0'),
      jsonb_build_object('field', '__styles.paddingBottom', 'target', 'styles', 'path', 'paddingBottom', 'label', '下内边距', 'component', 'vxe-input', 'valueKind', 'string', 'defaultValue', '0'),
      jsonb_build_object('field', '__styles.paddingLeft', 'target', 'styles', 'path', 'paddingLeft', 'label', '左内边距', 'component', 'vxe-input', 'valueKind', 'string', 'defaultValue', '0')
    ),
    'layout', jsonb_build_array(jsonb_build_object(
      'kind', 'tabs',
      'defaultKey', 'basic',
      'tabs', jsonb_build_array(
        jsonb_build_object('key', 'basic', 'label', '基础', 'blocks', $layout$[{"kind":"field","field":"__block._vid"},{"kind":"field","field":"title"},{"kind":"field","field":"chartType"},{"kind":"field","field":"color"}]$layout$::jsonb),
        jsonb_build_object('key', 'data', 'label', '数据', 'blocks', $layout$[{"kind":"field","field":"categoriesJson"},{"kind":"field","field":"seriesDataJson"},{"kind":"field","field":"pieDataJson"},{"kind":"field","field":"radarIndicatorsJson"},{"kind":"field","field":"radarDataJson"},{"kind":"field","field":"optionJson"}]$layout$::jsonb),
        jsonb_build_object('key', 'style', 'label', '样式', 'blocks', $layout$[{"kind":"field","field":"__styles.justifyContent"},{"kind":"field","field":"__styles.tempPadding"},{"kind":"field","field":"__styles.paddingTop"},{"kind":"field","field":"__styles.paddingRight"},{"kind":"field","field":"__styles.paddingBottom"},{"kind":"field","field":"__styles.paddingLeft"}]$layout$::jsonb)
      )
    )),
    'actions', jsonb_build_array()
  ),
  true
from chart_materials
on conflict (code) do update set
  name = excluded.name,
  description = excluded.description,
  schema = excluded.schema,
  enabled = excluded.enabled;

